export function getTemplateProject(
  slug: string
): TemplateProject | undefined {
  return templateProjects.find((p) => p.slug === slug)
}

export function getRelatedTemplateProjects(
  project: TemplateProject,
  limit = 3
): TemplateProject[] {
  const isWebsite = project.category === "website"
  const sameSurface = (p: TemplateProject) =>
    isWebsite ? p.category === "website" : p.category !== "website"

  return templateProjects
    .filter(
      (p) =>
        p.slug !== project.slug &&
        sameSurface(p) &&
        p.category === project.category
    )
    .concat(
      templateProjects.filter(
        (p) =>
          p.slug !== project.slug &&
          sameSurface(p) &&
          p.category !== project.category
      )
    )
    .slice(0, limit)
}

